    <div id="editor"></div>
    <div id="terminal-panel">
      <div id="terminal-header" onclick="toggleTerminal()">
        <span>▶ 终端</span><span id="term-toggle">▼</span>
      </div>
      <div id="terminal-output"></div>
      <div id="terminal-input-row">
        <span>PS&gt;</span>
        <input id="terminal-input" placeholder="输入命令..." autocomplete="off">
      </div>
    </div>
  </div>
</div>
<div id="status"></div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.45.0/min/vs/loader.min.js"></script>
<script>
let currentFile = null;
let currentDir = '';

require.config({paths:{vs:'https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.45.0/min/vs'}});
let editor;
require(['vs/editor/editor.main'],function(){
  editor = monaco.editor.create(document.getElementById('editor'),{
    value: '// 选择一个文件开始编辑\n',
    language: 'plaintext',
    theme: 'vs-dark',
    automaticLayout: true,
    fontSize: 14,
    minimap: {enabled: false},
    scrollBeyondLastLine: false
  });
  loadDir('');
  editor.addAction({id:'save',label:'Save',keybindings:[monaco.KeyMod.CtrlCmd|monaco.KeyCode.KeyS],run:saveFile});
});

document.getElementById('terminal-input').addEventListener('keydown',function(e){
  if(e.key==='Enter'){runCmd();}
});

async function loadDir(dir){
  currentDir = dir;
  const res = await fetch('/api/files?path='+encodeURIComponent(dir));
  const data = await res.json();
  const list = document.getElementById('file-list');
  list.innerHTML = '';
  if(dir){
    const parent = dir.split('/').slice(0,-1).join('/')||'';
    const li = document.createElement('li');
    li.className = 'dir';
    li.innerHTML = '<span class="icon">📁</span>..';
    li.onclick = ()=>loadDir(parent);
    list.appendChild(li);
  }
  data.forEach(f=>{
    const li = document.createElement('li');
    li.className = f.type==='dir'?'dir':'file';
    li.innerHTML = (f.type==='dir'?'<span class="icon">📁</span>':'<span class="icon">📄</span>')+f.name;
    li.onclick = ()=>{
      if(f.type==='dir'){loadDir(f.path)}
      else{openFile(f.path)}
    };
    list.appendChild(li);
  });
}

async function openFile(path){
  currentFile = path;
  const res = await fetch('/api/file?path='+encodeURIComponent(path));
  const data = await res.json();
  document.getElementById('current-path').textContent = path;
  const ext = path.split('.').pop();
  const langMap = {py:'python',js:'javascript',ts:'typescript',html:'html',css:'css',json:'json',md:'markdown',svg:'xml',txt:'plaintext',yaml:'yaml',yml:'yaml',sh:'shell',ps1:'powershell',bat:'bat',xml:'xml',csv:'plaintext',env:'plaintext',gitignore:'plaintext'};
  monaco.editor.setModelLanguage(editor.getModel(), langMap[ext]||'plaintext');
  editor.setValue(data.content);
  showStatus('已打开: '+path);
}

async function saveFile(){
  if(!currentFile){showStatus('请先选择一个文件','error');return}
  const content = editor.getValue();
  const res = await fetch('/api/file?path='+encodeURIComponent(currentFile),{method:'POST',body:content});
  if(res.ok){showStatus('已保存: '+currentFile)}
  else{showStatus('保存失败','error')}
}

let termVisible = true;
function toggleTerminal(){
  termVisible = !termVisible;
  document.getElementById('terminal-output').style.display = termVisible?'block':'none';
  document.getElementById('terminal-input-row').style.display = termVisible?'flex':'none';
  document.getElementById('term-toggle').textContent = termVisible?'▼':'▲';
}

async function runCmd(){
